pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // fuzz the amount passed to AdjustBetAmounts; for the reference contract,
    // after the owner calls AdjustBetAmounts(amount) the public getter currentBetLimit()
    // must equal the provided amount for ANY amount. The mutant that always assigns 0
    // will violate this for any non-zero amount, so the fuzzer can find such an input.
    function testFuzz_property(uint256 amount) public {
        // keep the domain wide; no restrictive assumes so the fuzzer can try non-zero values

        // caller is the owner (setUp deployed c with address(this) as owner via new C(address(this),0))
        // call AdjustBetAmounts with the fuzzed amount
        c.AdjustBetAmounts(amount);

        // exactly one assertion: the contract's public view currentBetLimit() must equal the passed amount
        // This holds for the reference and fails for the mutant when amount != 0
        assertTrue(c.currentBetLimit() == amount);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract and check the general rule: AdjustBetAmounts(amount) sets bet limit to amount.
    // This holds for original P (which sets betLimit = amount) and is violated by M (which sets betLimit = amount/2).
    function runTest(uint256 amount) public {
        // onlyOwner modifier on AdjustBetAmounts requires caller == owner of C.
        // We cannot become owner here, so we use the fact that the test must only call public surface.
        // However AdjustBetAmounts is onlyOwner; to exercise it we rely on the contract's owner being this caller in the verification environment.
        // Call AdjustBetAmounts to set the bet limit.
        c.AdjustBetAmounts(amount);

        // Read the publicly exposed currentBetLimit and assert it equals the input amount.
        uint256 observed = c.currentBetLimit();
        assert(observed == amount);
