    // fallback and receive left empty — not used but allowed per instructions.
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Drive minimal sequence: call AdjustBetAmounts from this contract and assert it cannot change the bet limit
    // We accept the newAmount as input. If the call succeeds, that indicates mutant behavior; on original it should revert.
    function run(uint256 newAmount) public {
        uint256 before = c.currentBetLimit();

        // Attempt call that should be restricted to owner in the original contract.
        // We capture whether it reverted by using low-level call on c.adjustBetAmounts via address(c).
        (bool success, ) = address(c).call(abi.encodeWithSignature("AdjustBetAmounts(uint256)", newAmount));

        uint256 after = c.currentBetLimit();

        // In original contract P, non-owner (this contract) cannot call AdjustBetAmounts, so call must fail and betLimit unchanged.
        // In mutant M the inverted check allows non-owners, so call succeeds and betLimit may change. We assert original behavior:
        assert(!success && after == before);
    }

    // allow receiving ETH if needed by caller (not used here)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // ensure caller is not the owner by assuming AdjustBetAmounts would revert on original
        // Establish a state that might matter: call play to follow the original counterexample order
        // play requires the caller to have previously wagered; but we cannot satisfy that easily here,
        // so we call play expecting it to revert; that's acceptable as long as AdjustBetAmounts behavior is tested.
        // Call play (may revert); we ignore its revert by wrapping in try/catch to continue.
        try c.play() {
            // no-op if succeeded
        } catch {
            // ignore revert
        }

        bool reverted;
        try c.AdjustBetAmounts(1) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the caller is not the contract owner, AdjustBetAmounts must revert.
        // We cannot call owner(), so express rule in terms of reverted flag and msg.sender != address(0)
        // Ensure that AdjustBetAmounts does not succeed when called from this address (a non-owner in P).
        assert(reverted);
    }
    receive() external payable {}
}

